describe('Checkout Form Required Field Validation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display error when postal code is missing on checkout form', () => {
    // Login with standard user
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Add backpack to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();

    // Open cart
    cy.get('[data-testid="shopping_cart_link"]').click();

    // Proceed to checkout
    cy.get('[data-testid="checkout"]').click();

    // Fill only first name and last name
    cy.get('[data-testid="first-name"]').type('Saif');
    cy.get('[data-testid="last-name"]').type('Afzal');

    // Attempt to continue without filling postal code
    cy.get('[data-testid="continue-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Postal Code is required');

    // Verify form is still visible
    cy.get('[data-testid="checkout-form"]').should('be.visible');
  });

  it('should successfully submit checkout form when all required fields are filled', () => {
    // Login with standard user
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Add backpack to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();

    // Open cart
    cy.get('[data-testid="shopping_cart-link"]').click();

    // Proceed to checkout
    cy.get('[data-testid="checkout"]').click();

    // Fill all required fields
    cy.get('[data-testid="first-name"]').type('Saif');
    cy.get('[data-testid="last-name"]').type('Afzal');
    cy.get('[data-testid="postal-code"]').type('12345');
    cy.get('[data-testid="email"]').type('saif@example.com');

    // Click continue button
    cy.get('[data-testid="continue-button"]').click();

    // Verify success message or next step is reached
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Checkout successful');

    // Verify error container is not visible
    cy.get('[data-testid="error"]').should('not.exist');
  });
});
